import com.kobil.wrapper.events.*

data class SdkFailure(val eventName: String, val errorType: String,
    val errorDescription: String, val errorCode: Long)

// Keep in memory; redact descriptions before writing/exporting logs.
fun sdkFailure(event: EventFrameworkEvent): SdkFailure? {
    val name = when (event) {
        is WarningEvent -> "Warning"
        is RuntimeErrorEvent -> "RuntimeError"
        is FatalErrorEvent -> "FatalError"
        else -> return null
    }
    val error = event as AbstractErrorEvent
    return SdkFailure(name, error.errorType.name, error.errorDescription,
        error.errorCode.toLong() and 0xffffffffL)
}

