import Foundation
import KSMasterController

struct SDKFailure {
    let eventName: String
    let errorType: String
    let errorDescription: String
    let errorCode: UInt32
}

// Keep this in memory; redact descriptions before writing/exporting logs.
func sdkFailure(_ event: KsMacroEvent) -> SDKFailure? {
    switch event {
    case let warning as KSMWarningEvent:
        return SDKFailure(eventName: "Warning", errorType: String(describing: warning.errorStatus),
            errorDescription: warning.errorDescription, errorCode: UInt32(bitPattern: warning.errorCode))
    case let runtime as KSMErrorRuntimeEvent:
        return SDKFailure(eventName: "RuntimeError", errorType: String(describing: runtime.errorType),
            errorDescription: runtime.errorDescription, errorCode: UInt32(bitPattern: runtime.errorCode))
    case let fatal as KSMErrorFatalEvent:
        return SDKFailure(eventName: "FatalError", errorType: String(describing: fatal.errorType),
            errorDescription: fatal.errorDescription, errorCode: UInt32(bitPattern: fatal.errorCode))
    default:
        return nil
    }
}
